ALTER POLICY "func insere fechamento do dia" ON public.fechamentos WITH CHECK (public.has_role(auth.uid(), 'funcionario') AND unidade_id = public.minha_unidade() AND data = public.hoje_sp() AND enviado_por = auth.uid());
ALTER POLICY "func le fechamento do dia" ON public.fechamentos USING (public.has_role(auth.uid(), 'funcionario') AND unidade_id = public.minha_unidade() AND data = public.hoje_sp());
ALTER POLICY "func insere fotos do dia" ON public.fotos WITH CHECK (public.has_role(auth.uid(), 'funcionario') AND EXISTS (SELECT 1 FROM public.fechamentos f WHERE f.id = fotos.fechamento_id AND f.unidade_id = public.minha_unidade() AND f.data = public.hoje_sp() AND f.enviado_por = auth.uid()) AND split_part(path, '/', 1) = public.minha_unidade()::text AND split_part(path, '/', 2) = public.hoje_sp()::text);
ALTER POLICY "func le fotos do dia" ON public.fotos USING (public.has_role(auth.uid(), 'funcionario') AND EXISTS (SELECT 1 FROM public.fechamentos f WHERE f.id = fotos.fechamento_id AND f.unidade_id = public.minha_unidade() AND f.data = public.hoje_sp()));
ALTER POLICY "func envia fotos da unidade" ON storage.objects WITH CHECK (bucket_id = 'fotos-caixa' AND public.has_role(auth.uid(), 'funcionario') AND (storage.foldername(name))[1] = public.minha_unidade()::text AND (storage.foldername(name))[2] = public.hoje_sp()::text);
ALTER POLICY "func le fotos da unidade" ON storage.objects USING (bucket_id = 'fotos-caixa' AND (public.has_role(auth.uid(), 'dono') OR (public.has_role(auth.uid(), 'funcionario') AND (storage.foldername(name))[1] = public.minha_unidade()::text AND (storage.foldername(name))[2] = public.hoje_sp()::text)));